/* Extract prices from compact storage */
function getP(key) {
  const r = P[key];
  if (!r) return [];
  const out = [];
  for (let i = 0; i < r.v.length; i++) {
    if (r.v[i] !== 0) out.push({ date: DT[r.s + i], value: r.v[i] });
  }
  return out;
}

/* Math */
function mRet(p) {
  const r = [];
  for (let i = 1; i < p.length; i++)
    if (p[i - 1].value && p[i].value)
      r.push({ date: p[i].date, ret: p[i].value / p[i - 1].value - 1 });
  return r;
}
function filt(d, s, e) { return d.filter(x => x.date >= s && x.date <= e); }
function avg(a) { return a.reduce((s, x) => s + x, 0) / a.length; }
function stdev(a) { const m = avg(a); return Math.sqrt(a.reduce((s, x) => s + (x - m) ** 2, 0) / (a.length - 1)); }

function calc(vP, eP, rf) {
  const vR = mRet(vP), eR = mRet(eP);
  const eD = new Set(eR.map(x => x.date));
  const va = vR.filter(x => eD.has(x.date));
  const vDates = new Set(va.map(x => x.date));
  const ea = eR.filter(x => vDates.has(x.date));
  if (va.length < 3) return null;
  const vr = va.map(x => x.ret), er = ea.map(x => x.ret), n = vr.length;
  const rfm = Math.pow(1 + rf, 1 / 12) - 1;
  const vC = vr.reduce((c, r) => c * (1 + r), 1);
  const eC = er.reduce((c, r) => c * (1 + r), 1);
  const yr = n / 12;
  const vA = Math.pow(vC, 1 / yr) - 1, eA = Math.pow(eC, 1 / yr) - 1;
  const vV = stdev(vr) * Math.sqrt(12), eV = stdev(er) * Math.sqrt(12);
  const vS = (vA - rf) / vV, eS = (eA - rf) / eV;
  const mv = avg(vr), me = avg(er);
  const cov = vr.reduce((s, v, i) => s + (v - mv) * (er[i] - me), 0) / (n - 1);
  const vv = vr.reduce((s, v) => s + (v - mv) ** 2, 0) / (n - 1);
  const beta = cov / vv;
  const alpha = (me - rfm - beta * (mv - rfm)) * 12;
  const dr = vr.map((v, i) => er[i] - v);
  const te = stdev(dr) * Math.sqrt(12);
  const mdd = (rs) => { let p = 1, m = 0, c = 1; for (const r of rs) { c *= (1 + r); p = Math.max(p, c); m = Math.min(m, c / p - 1); } return m; };
  const cs = [{ date: va[0].date, van: 100, esg: 100 }];
  let cv = 100, ce = 100;
  for (let i = 0; i < n; i++) {
    cv *= (1 + vr[i]); ce *= (1 + er[i]);
    cs.push({ date: va[i].date, van: +cv.toFixed(2), esg: +ce.toFixed(2) });
  }
  return {
    n, s0: va[0].date, s1: va[n - 1].date,
    va: { a: vA, c: vC - 1, vo: vV, sh: vS, md: mdd(vr) },
    es: { a: eA, c: eC - 1, vo: eV, sh: eS, md: mdd(er), beta, alpha, te },
    cs
  };
}

const pc = (v, d = 2) => v != null ? (v * 100).toFixed(d) + "%" : "--";
const nm = (v, d = 3) => v != null ? v.toFixed(d) : "--";

